  const ctl=d.controls||{};
  content.innerHTML=hero('Controlled drafts','Maker-checker workflow in the separate operational database','Real posting disabled')+`<div class="metrics control-metrics">${metric('Stock positions',num(ctl.stock_positions),'Reconciled operational balances')}${metric('Active reservations',num(ctl.active_reservations),'Protected from double allocation')}${metric('Open periods',num(ctl.open_rehearsal_periods),'Rehearsal permission only')}${metric('Permanent postings',num(ctl.permanent_journals),'Must remain zero')}</div>`+formPanel+`<section class="panel draft-list"><div class="panel-head"><h3>Operational workflow queue</h3><span>${num(d.total)} records</span></div><div class="table-wrap"><table><thead><tr><th>Created</th><th>Draft</th><th>Type</th><th>Party</th><th>Location</th><th>Lines</th><th>Total</th><th>Status</th><th>Actions</th></tr></thead><tbody>${d.items.length?d.items.map(x=>`<tr><td>${esc(date(x.created_at))}</td><td>${esc(x.draft_no)}<small>Rev ${x.revision}</small></td><td>${esc(x.document_type)}</td><td>${esc(x.party_name)}</td><td>${esc(x.location_code)}</td><td>${num(x.lines.length)}</td><td class="money">${esc(money(x.total_amount))}</td><td><span class="status ${esc(x.status)}">${esc(x.status)}</span></td><td class="row-actions">${actionButtons(x)}</td></tr>`).join(''):'<tr><td colspan="9" class="empty">No operational drafts created yet</td></tr>'}</tbody></table></div><p id="workflow-result" class="footer-note workflow-result"></p></section>`;
  async function mutate(url,payload){const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(payload)}),body=await r.json().catch(()=>({}));if(!r.ok)throw Error(body.detail||'Workflow action failed');return body}
  document.querySelectorAll('.draft-transition').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await mutate(`/api/v1/drafts/${b.dataset.key}/${b.dataset.action}`,{expected_revision:Number(b.dataset.revision)});await draftWorkspace()}catch(e){alert(e.message);b.disabled=false}});
  document.querySelectorAll('.draft-rehearse').forEach(b=>b.onclick=async()=>{b.disabled=true;const out=document.querySelector('#workflow-result');out.textContent='Running transactional rehearsal…';try{const r=await mutate(`/api/v1/drafts/${b.dataset.key}/posting-rehearsal`,{});out.textContent=`Balanced AED ${num(r.debit)} debit and credit; COGS AED ${num(r.cost_of_goods_sold)}; ${num(r.inventory.length)} stock probes staged; rollback verified; no posting performed.`}catch(e){out.textContent=e.message;b.disabled=false}});
