  function bindLines(){document.querySelectorAll('.remove-line').forEach(b=>b.onclick=()=>{if(document.querySelectorAll('.draft-line').length>1)b.closest('tr').remove()});document.querySelectorAll('[name=sku]').forEach(input=>{input.oninput=()=>{clearTimeout(input.searchTimer);input.searchTimer=setTimeout(()=>loadProducts(input.value),250)};input.onchange=()=>{const p=products.get(input.value.trim()),row=input.closest('tr');if(p){row.querySelector('[name=uom]').value=p.uom||'';const price=form.document_type.value==='sale'?p.selling_price_evidence:p.purchase_price_evidence;if(price!==null&&price!==undefined)row.querySelector('[name=unit_price]').value=price}}})}
  function addPopulatedLine(x){lineBody.insertAdjacentHTML('beforeend',draftLine());const r=lineBody.lastElementChild;r.querySelector('[name=sku]').value=x.sku;r.querySelector('[name=quantity]').value=x.quantity;r.querySelector('[name=uom]').value=x.uom;r.querySelector('[name=unit_price]').value=x.unit_price;r.querySelector('[name=tax_rate]').value=x.tax_rate}
  await Promise.all([loadLocations(),loadParties(),loadProducts()]);bindLines();
